'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),os=require('node:os'),net=require('node:net'),dgram=require('node:dgram'),crypto=require('node:crypto'),{spawn}=require('node:child_process');
const {Sessions}=require('../sessions'),relay=require('../relay/client');
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function port(){const s=net.createServer();await new Promise(r=>s.listen(0,'127.0.0.1',r));const p=s.address().port;await new Promise(r=>s.close(r));return p;}
async function fixture(t,kind,target){const root=fs.mkdtempSync(path.join(os.tmpdir(),'terminal-relay-test-'));const state=fs.mkdtempSync(path.join(os.tmpdir(),'terminal-relay-state-'));const m=new Sessions(),ui={storageRoot:root,stateRoot:state,workbench:true},ai={...ui,workbench:false};const key=crypto.randomBytes(32).toString('base64'),listen=await port();const rec=(await m.create(ui,{kind,...target,visibleToAide:false,relay:{enabled:true,host:'127.0.0.1',port:listen,key}})).session;const script=m.relayScript(ui,{id:rec.id});const file=path.join(root,'relay.py');fs.writeFileSync(file,Buffer.from(script.data,'base64'),{mode:0o600});let agent;
 t.after(async()=>{await m.stop();if(agent&&agent.exitCode===null){const closed=new Promise(r=>agent.once('exit',r));agent.kill();await closed;}fs.rmSync(root,{recursive:true,force:true});fs.rmSync(state,{recursive:true,force:true});});
 return {root,state,m,ui,ai,rec,key,listen,start:async()=>{agent=spawn('python3',[file],{stdio:['ignore','pipe','pipe']});let err='';agent.stderr.on('data',d=>err+=d);await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('agent startup '+err)),8000);agent.once('exit',()=>{clearTimeout(timer);reject(Error('agent exit '+err));});agent.stdout.once('data',()=>{clearTimeout(timer);resolve();});});},config:()=>m.relayConfig(m.space(ui),m.get(m.space(ui),rec.id,ui))};}
async function received(m,context,id,hex){for(let i=0;i<100;i++){const result=m.poll(context,{id,offset:0});if(Buffer.from(result.output.data,'base64').toString().includes('RX')&&Buffer.from(result.output.data,'base64').toString().includes(hex))return;await wait(25);}throw Error('missing relay echo '+hex);}
test('configured Python TLS relay transfers TCP bytes, probes without opening target and hides sessions',async t=>{
 let connections=0;const server=net.createServer(s=>{connections++;s.on('error',()=>{});s.on('data',d=>s.write(d));});await new Promise(r=>server.listen(0,'127.0.0.1',r));t.after(()=>new Promise(r=>server.close(r)));
 const f=await fixture(t,'tcp',{host:'127.0.0.1',port:server.address().port});assert.equal(f.rec.kind,'tcp');assert.equal(f.rec.status,'waiting');assert.equal(f.m.list(f.ai).sessions.length,0);assert.throws(()=>f.m.poll(f.ai,{id:f.rec.id}),/不存在/);assert.throws(()=>f.m.relayScript(f.ai,{id:f.rec.id}),/工作台/);assert.throws(()=>f.m.visibility(f.ai,{id:f.rec.id,visible:true}),/工作台/);
 await f.start();assert.equal((await f.m.relayStatus(f.ui,{id:f.rec.id})).session.relayOnline,'online');assert.equal(connections,0);
 await assert.rejects(relay.open({...f.config(),key:crypto.randomBytes(32).toString('base64')},'probe'),/身份/);assert.equal(connections,0);
 await f.m.relayConnect(f.ui,{id:f.rec.id});await f.m.send(f.ui,{id:f.rec.id,data:'41 00 ff',format:'hex'});await received(f.m,f.ui,f.rec.id,'41 00 ff');assert.equal(connections,1);
 assert.throws(()=>f.m.send(f.ai,{id:f.rec.id,data:'secret'}),/不存在/);assert.throws(()=>f.m.logs(f.ai,{id:f.rec.id}),/不存在/);await assert.rejects(f.m.commCall(f.ai,{action:'tcp_close',arguments:{}}),/可见会话/);
 f.m.visibility(f.ui,{id:f.rec.id,visible:true});assert.equal(f.m.list(f.ai).sessions.length,1);await f.m.send(f.ai,{id:f.rec.id,data:'VISIBLE'});await received(f.m,f.ui,f.rec.id,'56 49 53 49 42 4c 45');assert(!JSON.stringify(f.m.list(f.ai)).includes(f.key));assert(!fs.existsSync(path.join(f.root,'.aide','terminal-workbench')));await f.m.close(f.ui,{id:f.rec.id});f.m.remove(f.ui,{id:f.rec.id});assert(!fs.existsSync(path.join(f.m.space(f.ui).dir,f.rec.id+'.relay.json')));
});
test('UDP datagram boundaries and binary data survive TCP/TLS relay framing',async t=>{
 const server=dgram.createSocket('udp4');await new Promise(r=>server.bind(0,'127.0.0.1',r));server.on('message',(data,r)=>server.send(data,r.port,r.address));t.after(()=>server.close());const f=await fixture(t,'udp',{host:'127.0.0.1',port:server.address().port});await f.start();await f.m.relayConnect(f.ui,{id:f.rec.id});await f.m.send(f.ui,{id:f.rec.id,data:'00 ff',format:'hex'});await f.m.send(f.ui,{id:f.rec.id,data:'41 42',format:'hex'});await received(f.m,f.ui,f.rec.id,'00 ff');await received(f.m,f.ui,f.rec.id,'41 42');await f.m.close(f.ui,{id:f.rec.id});
});
test('serial target on relay uses remote pyserial and preserves binary UART traffic',async t=>{
 const {SerialPort}=require('serialport');const setup=fs.mkdtempSync(path.join(os.tmpdir(),'relay-serial-source-')),manager=new Sessions();t.after(async()=>{await manager.stop();fs.rmSync(setup,{recursive:true,force:true});});const pair=await manager.commCall(setup,{action:'serial_virtual_create'});
 const echo=new SerialPort({path:pair.slavePath,baudRate:115200});await new Promise((r,j)=>{echo.once('open',r);echo.once('error',j);});echo.on('error',()=>{});echo.on('data',data=>echo.write(data));t.after(()=>new Promise(r=>echo.close(r)));
 const f=await fixture(t,'serial',{devicePath:pair.masterPath,baudRate:115200});await f.start();await f.m.relayConnect(f.ui,{id:f.rec.id});assert.equal(f.m.get(f.m.space(f.ui),f.rec.id,f.ui).relaySocket.getProtocol(),'TLSv1.3');await f.m.send(f.ui,{id:f.rec.id,data:'41 00 ff',format:'hex'});await received(f.m,f.ui,f.rec.id,'41 00 ff');await f.m.close(f.ui,{id:f.rec.id});
});
test('SSH retains original kind and verifies device host key through encrypted relay',async t=>{
 const {Server}=require('ssh2');const host=crypto.generateKeyPairSync('rsa',{modulusLength:2048,privateKeyEncoding:{type:'pkcs1',format:'pem'},publicKeyEncoding:{type:'pkcs1',format:'pem'}}).privateKey;const clients=new Set();
 const ssh=new Server({hostKeys:[host]},client=>{clients.add(client);client.on('error',()=>{});client.on('close',()=>clients.delete(client));client.on('authentication',ctx=>ctx.method==='password'&&ctx.password==='relay-fixture'?ctx.accept():ctx.reject(['password']));client.on('ready',()=>client.on('session',accept=>{const session=accept();session.on('pty',accept=>accept());session.on('shell',accept=>{const stream=accept();stream.write('RELAY_SSH_READY\r\n');stream.on('data',data=>stream.write('ECHO:'+data));});}));});await new Promise(r=>ssh.listen(0,'127.0.0.1',r));t.after(()=>{for(const c of clients)c.end();ssh.close();});
 const f=await fixture(t,'ssh',{host:'127.0.0.1',port:ssh.address().port,username:'device',auth:'password'});await f.start();await f.m.relayConnect(f.ui,{id:f.rec.id});
 const output=()=>Buffer.from(f.m.poll(f.ui,{id:f.rec.id}).output.data,'base64').toString();async function until(pattern){for(let i=0;i<200;i++){if(pattern.test(output()))return;await wait(25);}throw Error('SSH output timeout '+pattern+' '+output());}
 await until(/authenticity|fingerprint/);f.m.send(f.ui,{id:f.rec.id,data:'yes\r'});await until(/password/i);f.m.send(f.ui,{id:f.rec.id,data:'relay-fixture\r'});await until(/RELAY_SSH_READY/);assert.equal(f.m.list(f.ui).sessions[0].kind,'ssh');assert(!output().includes(f.key));await f.m.close(f.ui,{id:f.rec.id});
});
test('hidden visibility persists across restart and prevents direct control or privilege spoofing',async t=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'relay-visibility-')),state=fs.mkdtempSync(path.join(os.tmpdir(),'relay-visibility-state-')),ui={storageRoot:root,stateRoot:state,workbench:true},ai={...ui,workbench:false};let m=new Sessions();t.after(async()=>{await m.stop();fs.rmSync(root,{recursive:true,force:true});fs.rmSync(state,{recursive:true,force:true});});
 const rec=(await m.create(ui,{kind:'local',visibleToAide:false})).session;for(const method of ['poll','logs','logging','remove','resize'])assert.throws(()=>m[method](ai,{id:rec.id,enabled:false,workbench:true}),/不存在/);await assert.rejects(m.close(ai,{id:rec.id}),/不存在/);await m.close(ui,{id:rec.id});await m.stop();m=new Sessions();assert.equal(m.list(ai).sessions.length,0);assert.equal(m.list(ui).sessions.length,1);m.visibility(ui,{id:rec.id,visible:true});assert.equal(m.list(ai).sessions.length,1);
});
test('private-state migration preserves history, removes old workspace copies and never resurrects deleted sessions',async t=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'relay-migrate-root-')),state=fs.mkdtempSync(path.join(os.tmpdir(),'relay-migrate-state-'));let legacy=new Sessions();const rec=(await legacy.create(root,{kind:'local'})).session;await legacy.close(root,{id:rec.id});await legacy.stop();const oldDir=path.join(root,'.aide','terminal-workbench');assert(fs.existsSync(path.join(oldDir,rec.id+'.json')));
 const m=new Sessions(),ui={storageRoot:root,stateRoot:state,workbench:true};t.after(async()=>{await m.stop();fs.rmSync(root,{recursive:true,force:true});fs.rmSync(state,{recursive:true,force:true});});assert.equal(m.list(ui).sessions.length,1);assert(!fs.existsSync(path.join(oldDir,rec.id+'.json')));const privateDir=m.space(ui).dir;assert(fs.existsSync(path.join(privateDir,rec.id+'.json')));m.remove(ui,{id:rec.id});await m.stop();const next=new Sessions();assert.equal(next.list(ui).sessions.length,0);await next.stop();
});
test('relay server rejects missing authentication without opening the configured target',async t=>{
 let opened=0;const server=net.createServer(s=>{opened++;s.destroy();});await new Promise(r=>server.listen(0,'127.0.0.1',r));t.after(()=>new Promise(r=>server.close(r)));const f=await fixture(t,'tcp',{host:'127.0.0.1',port:server.address().port});await f.start();
 const tls=require('node:tls');await new Promise((resolve,reject)=>{const socket=tls.connect({host:'127.0.0.1',port:f.listen,rejectUnauthorized:false,minVersion:'TLSv1.3'});let text='',answered=false;socket.on('data',d=>{text+=d.toString();if(!answered&&text.includes('\n')){answered=true;text='';socket.write(JSON.stringify({id:f.config().id,mode:'open',proof:'0'.repeat(64)})+'\n');}});socket.on('error',reject);socket.on('close',resolve);});assert.equal(opened,0);
});
test('downloaded script treats quotes and replacement markers as literal configuration data',()=>{
 const {spawnSync}=require('node:child_process'),root=fs.mkdtempSync(path.join(os.tmpdir(),'relay-config-data-'));try{const config={id:'fixture',kind:'serial',devicePath:"COM3-$&-$'-quote\"",key:crypto.randomBytes(32).toString('base64')};const file=path.join(root,'relay.py');fs.writeFileSync(file,relay.script(config));const result=spawnSync('python3',['-c','import runpy,json,sys;print(json.dumps(runpy.run_path(sys.argv[1])["CONFIG"]))',file],{encoding:'utf8',timeout:5000});assert.equal(result.status,0,result.stderr);assert.deepEqual(JSON.parse(result.stdout),config);}finally{fs.rmSync(root,{recursive:true,force:true});}
});
